#:property AllowUnsafeBlocks=true

Span<nint> signed = stackalloc nint[4];
for (int i = 0; i < signed.Length; i++)
    signed[i] = i * 10;

Span<nuint> unsigned = stackalloc nuint[4];
for (int i = 0; i < unsigned.Length; i++)
    unsigned[i] = (nuint)(i * 100);

Console.WriteLine($"nint  element size : {sizeof(nint)} bytes");
Console.WriteLine($"nuint element size : {sizeof(nuint)} bytes");
Console.WriteLine($"Span<nint>  values : [{string.Join(", ", signed.ToArray())}]");
Console.WriteLine($"Span<nuint> values : [{string.Join(", ", unsigned.ToArray())}]");

